return ['x-generator'=>'GlotPress/4.1.0','translation-revision-date'=>'2026-03-13 16:55:13+0000','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n >= 2 && n <= 4) ? 1 : 2);','project-id-version'=>'Themes - Twenty Fourteen','language'=>'cs_CZ','messages'=>['In 2014, our default theme lets you create a responsive magazine website with a sleek, modern design. Feature your favorite homepage content in either a grid or a slider. Use the three widget areas to customize your website, and change your content\'s layout with a full-width page template and a contributor page to show off your authors. Creating a magazine website with WordPress has never been easier.'=>'Twenty Fourteen (2014) je nová výchozí šablona pro WordPress, která je ideální zejména pro různé magazíny. Jednou z hlavních předností je flexibilní a moderní vzhled, který se automaticky přizpůsobí různým zařízením. S její pomocí můžete snadno zvýraznit doporučený obsah webu a zobrazit ho v podobě pravidelné mřížky (dlaždice) nebo přehledného posunování jednotlivých položek. V šabloně jsou definovány celkem 3 oblasti pro widgety (levý a pravý postranní panel, zápatí), takže si můžete některé části webu snadno přizpůsobit. Twenty Fourteen obsahuje i speciální widget (určen pro zobrazování nejnovějších stručných příspěvků) a volitelné šablony pro stránky (přehled autorů webu a zobrazení bez pravého postranního panelu). Tvorba vlastního webového magazínu ve WordPressu ještě nikdy nebyla snadnější a příjemnější.','Twenty Fourteen'=>'Twenty Fourteen',2016=>'2016',2012=>'2012',2001=>'2001','List'=>'Seznam','GET IN TOUCH'=>'SPOJTE SE S NÁMI','Don’t hesitate to reach out.'=>'Neváhejte nás kontaktovat.','GOT A QUESTION?'=>'MÁTE DOTAZ?','Write title…'=>'Napište název…','Contact'=>'Kontakt','Read More'=>'Číst více','Clouds'=>'Oblaka','Photo of a cloudy mountain'=>'Fotografie zamračené hory','Streetscape'=>'Pouliční scéna','Photo of a streetscape'=>'Fotografie pouliční scény','Bridge'=>'Most','Photo of a bridge'=>'Fotografie mostu','Sunset'=>'Západ slunce','Photo of a sunset'=>'Fotografie západu slunce','Here are some photos from my all-time favorite destinations.'=>'Zde je několik fotografií z mých nejoblíbenějších destinací.','Traveling Nostalgia'=>'Cestovatelská nostalgie','Summary'=>'Shrnutí','Hello, my name is Joan. I am passionate about writing, travel, and photography.'=>'Dobrý den, jmenuji se Joan. Jsem vášnivá spisovatelka, cestovatelka a fotografka.','I’ve traveled to over 60 countries, and have made many friends along the way. I created this website to keep track of the memories I’ve made in my years of traveling.'=>'Procestovala jsem více než 60 zemí a na své cestě jsem získala mnoho přátel. Tuto webovou stránku jsem vytvořila, abych si zaznamenávala vzpomínky, které jsem během let cestování získala.','A person standing in front of a lake'=>'Osoba stojící před jezerem','About'=>'O mně','My first year of traveling. I visited China, Thailand, Japan, and India.'=>'Můj první rok cestování. Navštívila jsem Čínu, Thajsko, Japonsko a Indii.','In 2012, I expanded my travels to Europe. I spent time in Poland, Germany, Italy, France, and Spain.'=>'V roce 2012 jsem rozšířila své cesty do Evropy. Pobývala jsem v Polsku, Německu, Itálii, Francii a Španělsku.','This year was devoted entirely to the western hemisphere. I went on a month-long road trip through the U.S.A. and Canada, and also visited Mexico, Brazil, and Colombia.'=>'Letošní ročník byl celý věnován západní polokouli. Vydala jsem se na měsíční cestu po USA a Kanadě a navštívila jsem také Mexiko, Brazílii a Kolumbii.','Medium Gray'=>'Středně šedá','Light Gray'=>'Světle šedá','White'=>'Bílá','Dark Gray'=>'Tmavě šedá','Green'=>'Zelená','Black'=>'Černá','comments titleOne thought on &ldquo;%s&rdquo;'=>'1 komentář u &bdquo;%s&ldquo;','comments title%1$s thought on &ldquo;%2$s&rdquo;'=>'%1$s komentář u &bdquo;%2$s&ldquo;' . "\0" . '%1$s komentáře u &bdquo;%2$s&ldquo;' . "\0" . '%1$s komentářů u &bdquo;%2$s&ldquo;','Full Width Page'=>'Stránka bez postranního panelu','Contributor Page'=>'Stránka s přehledem autorů','Tag Archives: %s'=>'Archiv štítku: %s','Search Results for: %s'=>'Výsledky vyhledávání pro: %s','Post format to show:'=>'Formát zobrazených příspěvků:','Number of posts to show:'=>'Počet zobrazených příspěvků:','Title:'=>'Název:','%s <span class="meta-nav">&rarr;</span>'=>'%s <span class="meta-nav">&rarr;</span>','This gallery contains <a href="%1$s" rel="bookmark">%2$s photo</a>.'=>'Galerie obsahuje <a href="%1$s" rel="bookmark">%2$s obrázek</a>.' . "\0" . 'Galerie obsahuje <a href="%1$s" rel="bookmark">%2$s obrázky</a>.' . "\0" . 'Galerie obsahuje <a href="%1$s" rel="bookmark">%2$s obrázků</a>.','Continue reading <span class="meta-nav">&rarr;</span>'=>'Celý příspěvek <span class="meta-nav">&rarr;</span>','More asides'=>'Další poznámky','Asides'=>'Poznámky','More galleries'=>'Další galerie','Galleries'=>'Galerie','More links'=>'Další odkazy','More quotes'=>'Další citace','Links'=>'Odkazy','Quotes'=>'Citace','More audio'=>'Další audio příspěvky','Audio'=>'Audio','More videos'=>'Další video příspěvky','Videos'=>'Video příspěvky','More images'=>'Další obrázky','Images'=>'Obrázky','Use this widget to list your recent Aside, Quote, Video, Audio, Image, Gallery, and Link posts.'=>'Speciální widget pro zobrazení nejnovějších stručných příspěvků (Poznámky, Citace, Video, Audio, Obrázky, Galerie a Odkazy).','Twenty Fourteen Ephemera'=>'Twenty Fourteen - Stručně','Sticky'=>'Zvýrazněný','<span class="meta-nav">Next Post</span>%title'=>'<span class="meta-nav">Další příspěvek</span>%title','<span class="meta-nav">Previous Post</span>%title'=>'<span class="meta-nav">Předchozí příspěvek</span>%title','<span class="meta-nav">Published In</span>%title'=>'<span class="meta-nav">Přiřazeno</span>%title','Post navigation'=>'Navigace pro příspěvky','Posts navigation'=>'Navigace pro příspěvky','Next &rarr;'=>'Další &rarr;','&larr; Previous'=>'&larr; Předchozí','Don&rsquo;t display tag on front end.'=>'Nezobrazovat štítek na webu.','Tag Name'=>'Název štítku','For an in-depth tutorial, and more tips and tricks, visit the <a href="%s">Twenty Fourteen documentation</a>.'=>'Podrobnější návod a další zajímavé tipy pro práci se šablonou naleznete v <a href="%s">manuálu pro Twenty Fourteen</a>.','Enhance your site design by using <a href="%s">Featured Images</a> for posts you&rsquo;d like to stand out (also known as post thumbnails). This allows you to associate an image with your post without inserting it. Twenty Fourteen uses featured images for posts and pages&mdash;above the title&mdash;and in the Featured Content area on the home page.'=>'Vzhled webu můžete ovlivnit také pomocí vhodných <a href="%s">náhledových obrázků</a>, a to zejména u příspěvků, které chcete nějakým způsobem zdůraznit. Snadno tak přiřadíte zvolený obrázek ke konkrétnímu příspěvku, aniž byste ho museli vkládat přímo do textu. Šablona Twenty Fourteen podporuje náhledové obrázky u příspěvků a stránek (jsou zobrazovány nad jejich názvem) a samozřejmě i v oblasti pro doporučené příspěvky na úvodní stránce.','The home page features your choice of up to 6 posts prominently displayed in a grid or slider, controlled by a <a href="%1$s">tag</a>; you can change the tag and layout in <a href="%2$s">Appearance &rarr; Customize</a>. If no posts match the tag, <a href="%3$s">sticky posts</a> will be displayed instead.'=>'Na úvodní stránce můžete nápadně zvýraznit až 6 příspěvků, které chcete návštěvníkům z nějakého důvodu doporučit, a zobrazit je buď v podobě pravidelné mřížky (dlaždice) nebo umožnit jejich přehledné posunování. Pro výběr doporučených příspěvků slouží speciální <a href="%1$s">štítek</a>, který lze snadno měnit (stejně jako způsob zobrazení) v menu <a href="%2$s">Vzhled &rarr; Přizpůsobit</a>. Pokud tímto způsobem nic neoznačíte, automaticky se budou zobrazovat <a href="%3$s">zvýrazněné příspěvky</a>.','Slider'=>'Posunovací položky','Grid'=>'Dlaždice (mřížka)','Layout'=>'Grafické rozvržení','featured content default tag slugfeatured'=>'doporuceno','Use a <a href="%1$s">tag</a> to feature your posts. If no posts match the tag, <a href="%2$s">sticky posts</a> will be displayed instead.'=>'Pro výběr doporučených příspěvků můžete použít speciální <a href="%1$s">štítek</a>. Pokud tímto způsobem nic neoznačíte, automaticky se budou zobrazovat <a href="%2$s">zvýrazněné příspěvky</a>.','Featured Content'=>'Doporučený obsah','May only be visible on wide screens.'=>'Nastavení bude použito pouze na dostatečně širokých zařízeních.','Background may only be visible on wide screens.'=>'Pozadí bude zobrazeno pouze na dostatečně širokých zařízeních.','Display Site Title &amp; Tagline'=>'Zobrazovat název a popis webu','Site Title Color'=>'Barva pro název webu','Twenty Fourteen requires at least WordPress version 3.6. You are running version %s. Please upgrade and try again.'=>'Šablona Twenty Fourteen vyžaduje alespoň WordPress 3.6, zatímco aktuálně používáte starší verzi %s. Nejdříve prosím proveďte aktualizaci a potom to můžete zkusit znovu.','Next Image'=>'Další obrázek','Previous Image'=>'Předchozí obrázek','Skip to content'=>'Přejít k obsahu webu','Primary Menu'=>'Základní navigační menu','Search'=>'Hledat','Page %s'=>'Stránky %s','%d Article'=>'%d příspěvek' . "\0" . '%d příspěvky' . "\0" . '%d příspěvků','Next'=>'Pokračovat','Previous'=>'Předchozí','Lato font: on or offon'=>'off','Appears in the footer section of the site.'=>'Hlavní oblast pro umístění widgetů, které se budou zobrazovat v zápatí webu.','Footer Widget Area'=>'Zápatí','Additional sidebar that appears on the right.'=>'Vedlejší postranní panel se zobrazuje v pravé části webu.','Content Sidebar'=>'Pravý postranní panel','Main sidebar that appears on the left.'=>'Hlavní postranní panel se zobrazuje v levé části webu.','Primary Sidebar'=>'Levý postranní panel','Secondary menu in left sidebar'=>'Vedlejší menu v levém postranním panelu','Top primary menu'=>'Hlavní navigační menu','Proudly powered by %s'=>'Používáme %s (v češtině).','It seems we can&rsquo;t find what you&rsquo;re looking for. Perhaps searching can help.'=>'Patrně jste chtěli na webu zobrazit něco, co se zde bohužel nenachází. Můžete ale ještě zkusit vyhledávání pomocí zadaného klíčového slova.','Sorry, but nothing matched your search terms. Please try again with some different keywords.'=>'Omlouváme se, ale hledaný výraz nebyl na webu nalezen. Zkuste to prosím znovu s nějakým jiným klíčovým slovem.','Ready to publish your first post? <a href="%s">Get started here</a>.'=>'Jste připraveni publikovat svůj první příspěvek? <a href="%s">Začněte zde</a>.','Nothing Found'=>'Nenalezeno','Pages:'=>'Stránky:','Continue reading %s <span class="meta-nav">&rarr;</span>'=>'Pokračování textu %s <span class="meta-nav">&rarr;</span>','Edit'=>'Upravit','% Comments'=>'Komentáře: %','1 Comment'=>'1 komentář','Leave a comment'=>'Napsat komentář','Used between list items, there is a space after the comma., '=>', ','Comments are closed.'=>'Komentáře nejsou povoleny.','Newer Comments &rarr;'=>'Novější komentáře &rarr;','&larr; Older Comments'=>'&larr; Starší komentáře','Comment navigation'=>'Navigace pro komentáře','Category Archives: %s'=>'Archiv rubriky: %s','All posts by %s'=>'Archiv autora: %s','Archives'=>'Archiv','yearly archives date formatY'=>'Y','Yearly Archives: %s'=>'Archiv pro rok: %s','monthly archives date formatF Y'=>'F Y','Monthly Archives: %s'=>'Archiv pro měsíc: %s','Daily Archives: %s'=>'Archiv pro den: %s','It looks like nothing was found at this location. Maybe try a search?'=>'Patrně jste chtěli zobrazit stránku, která se na webu bohužel nenachází. Můžete ale zkusit vyhledávání pomocí zadaného klíčového slova.','Not Found'=>'Nenalezeno','https://wordpress.org/'=>'https://cs.wordpress.org/','the WordPress team'=>'Vývojáři WordPressu (a překladatelé)','https://wordpress.org/themes/twentyfourteen/'=>'https://cs.wordpress.org/themes/twentyfourteen/']];